package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

type FastReader struct {
	reader *bufio.Reader
	tokens []string
	pos    int
}

func NewFastReader() *FastReader {
	return &FastReader{reader: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fr *FastReader) Next() string {
	for fr.tokens == nil || fr.pos >= len(fr.tokens) {
		line, err := fr.reader.ReadString('\n')
		if err != nil && len(line) == 0 {
			return ""
		}
		fr.tokens = splitTokens(line)
		fr.pos = 0
	}
	tok := fr.tokens[fr.pos]
	fr.pos++
	return tok
}

func splitTokens(s string) []string {
	res := make([]string, 0)
	cur := ""
	for _, c := range s {
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' {
			if len(cur) > 0 {
				res = append(res, cur)
				cur = ""
			}
		} else {
			cur += string(c)
		}
	}
	if len(cur) > 0 {
		res = append(res, cur)
	}
	return res
}

func (fr *FastReader) NextInt() int {
	v, _ := strconv.Atoi(fr.Next())
	return v
}

func (fr *FastReader) NextLong() int64 {
	v, _ := strconv.ParseInt(fr.Next(), 10, 64)
	return v
}

func (fr *FastReader) NextDouble() float64 {
	v, _ := strconv.ParseFloat(fr.Next(), 64)
	return v
}

func (fr *FastReader) NextLine() string {
	str, err := fr.reader.ReadString('\n')
	if err != nil && len(str) == 0 {
		return ""
	}
	for len(str) > 0 && (str[len(str)-1] == '\n' || str[len(str)-1] == '\r') {
		str = str[:len(str)-1]
	}
	return str
}

func (fr *FastReader) ReadIntArray(n int) []int {
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = fr.NextInt()
	}
	return a
}

func (fr *FastReader) ReadLongArray(n int) []int64 {
	a := make([]int64, n)
	for i := 0; i < n; i++ {
		a[i] = fr.NextLong()
	}
	return a
}

func (fr *FastReader) ReadDoubleArray(n int) []float64 {
	a := make([]float64, n)
	for i := 0; i < n; i++ {
		a[i] = fr.NextDouble()
	}
	return a
}

func main() {
	fs := NewFastReader()
	n := fs.NextLong()
	k := fs.NextLong()
	set := make(map[int64]bool)
	bool_ := true
	for i := int64(1); i <= k; i++ {
		rest := n % i
		if !set[rest] {
			set[rest] = true
		} else {
			bool_ = false
			break
		}
	}
	if bool_ {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
